-- Official Topps NOW #114–116; guarded catalogue-only append.
begin; set local lock_timeout='5s';
lock table public.catalogue_sets,public.catalogue_subsets,public.catalogue_cards,public.catalogue_variants,public.catalogue_sources,public.catalogue_parallel_rules,public.collection_items,public.reference_images in share row exclusive mode;
create temporary table before_catalogue_sets on commit drop as select case when t.id='2026-topps-now-wwe' then to_jsonb(t)-'card_count'-'variant_count'-'updated_at' else to_jsonb(t) end as row from public.catalogue_sets t;
create temporary table before_catalogue_subsets on commit drop as select case when t.set_id='2026-topps-now-wwe' and t.subset_code='BASE' then to_jsonb(t)-'card_count' else to_jsonb(t) end as row from public.catalogue_subsets t;
create temporary table before_catalogue_cards on commit drop as select to_jsonb(t) as row from public.catalogue_cards t;
create temporary table before_catalogue_variants on commit drop as select to_jsonb(t) as row from public.catalogue_variants t;
create temporary table before_catalogue_sources on commit drop as select to_jsonb(t) as row from public.catalogue_sources t;
create temporary table before_catalogue_parallel_rules on commit drop as select to_jsonb(t) as row from public.catalogue_parallel_rules t;
create temporary table before_collection_items on commit drop as select to_jsonb(t) as row from public.collection_items t;
create temporary table before_reference_images on commit drop as select to_jsonb(t) as row from public.reference_images t;
do $$ begin
      if (select count(*) from public.catalogue_cards where set_id='2026-topps-now-wwe') not in (137,140)
      or (select count(*) from public.catalogue_variants where set_id='2026-topps-now-wwe') not in (186,209)
      or exists(select 1 from public.catalogue_cards where set_id='2026-topps-now-wwe' and card_number in ('114','115','116') and id<>'2026-TNWWE-BASE-'||card_number)
      or exists(select 1 from public.catalogue_cards where set_id='2026-topps-now-wwe' and checklist_order between 138 and 140 and id not in ('2026-TNWWE-BASE-114','2026-TNWWE-BASE-115','2026-TNWWE-BASE-116'))
      or exists(select 1 from public.catalogue_variants where set_id='2026-topps-now-wwe' and variant_order between 187 and 209 and card_id not in ('2026-TNWWE-BASE-114','2026-TNWWE-BASE-115','2026-TNWWE-BASE-116'))
      then raise exception 'Unexpected annual baseline'; end if;
    end $$;
